def compute_score() -> tuple[str, float]:
    from pptx import Presentation
    import re
    prs = Presentation(modified_ppt_path)
    bad = []
    for i, s in enumerate(prs.slides):
        if i == 0: continue
        texts = " ".join(sh.text for sh in s.shapes if hasattr(sh, "text"))
        if not re.search(r"Lec 1\.%d" % (i + 1), texts) or re.search(r"Lec 3\.", texts):
            bad.append(i + 1)
    if bad:
        return f"Footers not updated on slides {bad}", 0.0
    return "All footers updated", 1.0

def compute_score() -> tuple[str, float]:
    from pptx import Presentation
    issues = []
    if ppt_diff.added_slides or ppt_diff.removed_slides:
        issues.append("slide count changed")
    if ppt_diff.added_animations or ppt_diff.removed_animations or ppt_diff.added_transitions or ppt_diff.removed_transitions:
        issues.append("animation/transition changes")
    o = Presentation(original_ppt_path); m = Presentation(modified_ppt_path)
    for i, (so, sm) in enumerate(zip(o.slides, m.slides)):
        if len(so.shapes) != len(sm.shapes):
            issues.append(f"shape count changed on slide {i+1}")
    if issues:
        return "Extraneous changes: " + "; ".join(issues), max(0.0, 1.0 - 0.3 * len(issues))
    return "No extraneous changes", 1.0
